PYTHONDONTWRITEBYTECODE=1 PYTHONMALLOC=pymalloc PYTHONPATH=peano-lab/py python3 - <<'PY'
import collections,hashlib,json,platform,resource,signal,sys,time
from pathlib import Path
resource.setrlimit(resource.RLIMIT_CPU,(170,175));signal.alarm(180)
t=time.perf_counter();cpu=time.process_time();directory=Path('research/arithmetic-library/working/prime-field-gcd-bezout-laws-v1');path=directory/'test_prime_field_polynomial_gcd_bezout_laws_candidate.py';reports=[];ids=[]
def pins():return {str(p):[p.stat().st_size,hashlib.sha256(p.read_bytes()).hexdigest()] for p in sorted(directory.glob('*.py'))}
def old_pins():
 return {str(p):[p.stat().st_size,hashlib.sha256(p.read_bytes()).hexdigest()] for p in sorted((directory.parent/'prime-field-euclidean-closure-v1').rglob('*')) if p.is_file()}
old_before=old_pins();before=pins()
class Ledger:
 def pytest_collection_finish(self,session):ids.extend(x.nodeid for x in session.items)
 def pytest_runtest_logreport(self,report):reports.append([report.nodeid,report.when,report.outcome,report.duration])
import pytest
args=['-q','-s','-p','no:cacheprovider',"research/arithmetic-library/working/prime-field-gcd-bezout-laws-v1/test_prime_field_polynomial_gcd_bezout_laws_candidate.py::test_native_original_conditional_body[prime_field_polynomial_aligned_add_empty_right]"]
code=pytest.main(args,plugins=[Ledger()]);peak=int(resource.getrusage(resource.RUSAGE_SELF).ru_maxrss)*(1 if platform.system()=='Darwin' else 1024);after=pins()
record={'args':args,'exit_code':int(code),'wall_seconds':time.perf_counter()-t,'cpu_seconds':time.process_time()-cpu,'peak_rss_bytes':peak,'cpu_limits':list(resource.getrlimit(resource.RLIMIT_CPU)),'wall_limit_seconds':180,'rss_limit_bytes':1536*1024*1024,'before':before,'after':after,'old95_before':old_before,'old95_after':old_pins(),'selected_ids':ids,'phases':dict(collections.Counter(r[1]+':'+r[2] for r in reports)),'failed_reports':[r for r in reports if r[2]!='passed'],'alpha_imports':[n for n in sys.modules if n.startswith('peano_lab.library.editions')],'dependency_complete':False,'lean_checked':False,'admitted':False}
print('GCD_BEZOUT_LAWS_OBSERVATION='+json.dumps(record,sort_keys=True,separators=(',',':')),flush=True)
assert old_before==old_pins()
assert before==after and peak<=1536*1024*1024 and not record['alpha_imports']
raise SystemExit(code)
PY

